import Products from "./Products";
import Cart from "./Cart";
import AddProduct from "./AddProduct";
import ProductProvider from "./store2/ProductProvider";
const HomePage=()=>{
  
    return(
        <div>
           <div style={{margin:"10px"}}><h1> Clothes Items</h1></div>
           <ProductProvider>
         <Products></Products>
           <Cart></Cart>
          <div>
          <AddProduct></AddProduct>
          </div>
          </ProductProvider>
        </div>
    )
}
export default HomePage;
